{
  "headline": "FDA's records show azithromycin 500 mg tablets from Proficient Rx LP are on the shortage list as To Be Discontinued since 2022-02-22; the labeler's plant was classified VAI 289 days after that posting",
  "headline_cites": ["E8", "E7", "D5"],
  "sentences": [
    {
      "text": "FDA's shortage list shows azithromycin tablets from Pfizer Inc. with status To Be Discontinued, first posted 2022-02-22.",
      "cites": ["E8"]
    },
    {
      "text": "Our 500 mg tablets at both Corvale sites carry NDC 71205067403, labeled by Proficient Rx LP (label 90605f94).",
      "cites": ["E4", "E2", "E7"]
    },
    {
      "text": "Proficient Rx LP's registered plant (FEI 3011557028) received a VAI classification on inspection 1194148 ending 2022-12-08, 289 days after the shortage posting.",
      "cites": ["E7", "D5", "E6"]
    },
    {
      "text": "As of 2026-10-21 the shortage has been on FDA's list for 56 months.",
      "cites": ["D6"]
    },
    {
      "text": "Corvale East has 7.6 days of 500 mg tablets on hand; Corvale General has 23.4 days.",
      "cites": ["D1", "D2"]
    },
    {
      "text": "The top-ranked action is to transfer 101 tablets of 500 mg from Corvale General to Corvale East, which would give Corvale East 14 days on hand while Corvale General retains two weeks.",
      "cites": ["D7"]
    },
    {
      "text": "Alternate manufacturers Advanced Rx Pharmacy of Tennessee, LLC and Advanced Rx of Tennessee, LLC are not on FDA's shortage list today and their labels name no plant we could place.",
      "cites": ["D8", "D9"]
    }
  ]
}
